SELECT $$a;b$$ AS body;
CREATE FUNCTION f() RETURNS int AS $body$ BEGIN RETURN 1; END; $body$ LANGUAGE plpgsql;
SELECT a::text, b::numeric(10,2) FROM t;
SELECT E'it\'s' AS s;
SELECT * FROM t WHERE id = $1;
SELECT doc->>'name', doc #> '{a,b}' FROM t;
INSERT INTO t (a) VALUES (1) ON CONFLICT (a) DO UPDATE SET a = EXCLUDED.a RETURNING *;
WITH RECURSIVE r(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 10) SELECT * FROM r;
SELECT count(*) FILTER (WHERE x > 0) OVER (PARTITION BY g ORDER BY t ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) FROM t;
SELECT ARRAY[1,2,3], arr[1], arr[1:2] FROM t;
SELECT * FROM t WHERE name ILIKE '%a%' AND tags @> ARRAY['x'];
SELECT "Mixed Case"."Col" FROM "Mixed Case";
SELECT 'a' || 'b', interval '1 day', now() - interval '2 hours';
DO $$ BEGIN RAISE NOTICE 'x'; END $$;
SELECT DISTINCT ON (a) a, b FROM t ORDER BY a, b DESC NULLS LAST;
CREATE INDEX CONCURRENTLY IF NOT EXISTS i ON t USING btree (a);
SELECT * FROM generate_series(1, 10) AS g(n) LEFT JOIN LATERAL (SELECT n * 2 AS m) x ON true;
EXPLAIN ANALYZE SELECT 1;
SELECT "a""b" FROM t;
SELECT café, naïve FROM t;
SELECT имя FROM t;
